export const GRAMMAR_Q=[
// ── WORD FORM (20) ──────────────────────────────────────────────
{id:'wf01',cat:'Word Form',s:'The company\'s financial _____ showed strong growth last quarter.',o:['A) perform','B) performance','C) performer','D) performed'],a:1,e:'Sau "The company financial" can mot DANH TU lam chu ngu. "Performance" (n) = hieu suat tai chinh la dung. Sai: "perform" (v), "performer" (n) = dien vien, "performed" (v qua khu).'},
{id:'wf02',cat:'Word Form',s:'All employees must attend the _____ training session this Friday.',o:['A) mandate','B) mandatory','C) mandated','D) mandatorily'],a:1,e:'Trước danh từ "training session" cần TÍNH TỪ. "Mandatory" (adj) = bắt buộc là đúng. "Mandate" (n/v) = lệnh/ra lệnh, "mandated" (adj/v) nghĩa gần nhưng ít dùng hơn, "mandatorily" (adv) không thể đứng trước danh từ.'},
{id:'wf03',cat:'Word Form',s:'The new system was implemented _____ across all departments.',o:['A) efficient','B) efficiency','C) efficiencies','D) efficiently'],a:3,e:'Sau động từ "implemented" cần TRẠNG TỪ bổ nghĩa. "Efficiently" (adv) = một cách hiệu quả là đúng. "Efficient" (adj) và "efficiency" (n) không thể bổ nghĩa cho động từ.'},
{id:'wf04',cat:'Word Form',s:'We appreciate your _____ in the annual conference.',o:['A) participate','B) participatory','C) participation','D) participant'],a:2,e:'Sau tính từ sở hữu "your" cần DANH TỪ. "Participation" (n) = sự tham gia là đúng. "Participate" (v), "participatory" (adj), "participant" (n nhưng nghĩa là người tham gia, không phải hành động).'},
{id:'wf05',cat:'Word Form',s:'The _____ of the new product exceeded all expectations.',o:['A) launch','B) launched','C) launching','D) launches'],a:0,e:'Sau mạo từ "The" cần DANH TỪ làm chủ ngữ. "Launch" (n) = sự ra mắt là đúng. "Launched" (v/adj), "launching" có thể dùng làm danh từ nhưng "launch" tự nhiên hơn.'},
{id:'wf06',cat:'Word Form',s:'Her _____ of the proposal surprised everyone on the board.',o:['A) reject','B) rejecting','C) rejection','D) rejected'],a:2,e:'Sau đại từ sở hữu "Her" cần DANH TỪ. "Rejection" (n) = sự từ chối là đúng. "Reject" (v), "rejecting" (v-ing), "rejected" (adj/v quá khứ) đều không phù hợp.'},
{id:'wf07',cat:'Word Form',s:'The director gave a very _____ speech at the annual meeting.',o:['A) inspire','B) inspiration','C) inspirational','D) inspirationally'],a:2,e:'Trước danh từ "speech" cần TÍNH TỪ. "Inspirational" (adj) = truyền cảm hứng là đúng. "Inspire" (v), "inspiration" (n), "inspirationally" (adv) không thể bổ nghĩa trực tiếp cho danh từ.'},
{id:'wf08',cat:'Word Form',s:'Please handle all customer complaints with _____ and care.',o:['A) patient','B) patiently','C) patience','D) impatient'],a:2,e:'Sau giới từ "with" cần DANH TỪ. "Patience" (n) = sự kiên nhẫn là đúng. "Patient" (adj/n) = kiên nhẫn/bệnh nhân, "patiently" (adv), "impatient" (adj) = thiếu kiên nhẫn (nghĩa ngược).'},
{id:'wf09',cat:'Word Form',s:'The sales team worked _____ to meet the quarterly target.',o:['A) tireless','B) tirelessly','C) tirelessness','D) tired'],a:1,e:'Sau động từ "worked" cần TRẠNG TỪ. "Tirelessly" (adv) = không mệt mỏi, kiên trì là đúng. "Tireless" (adj), "tirelessness" (n), "tired" (adj) = mệt mỏi (nghĩa ngược).'},
{id:'wf10',cat:'Word Form',s:'The _____ of the new office building will begin next spring.',o:['A) construct','B) constructive','C) construction','D) constructed'],a:2,e:'Sau mạo từ "The" cần DANH TỪ làm chủ ngữ. "Construction" (n) = sự xây dựng là đúng. "Construct" (v), "constructive" (adj) = mang tính xây dựng, "constructed" (v quá khứ).'},
{id:'wf11',cat:'Word Form',s:'Mr. Park is _____ for overseeing the marketing department.',o:['A) responsible','B) responsibility','C) responsibly','D) respond'],a:0,e:'Sau động từ "is" cần TÍNH TỪ (vị ngữ tính từ). "Responsible" (adj) + "for" = chịu trách nhiệm về là đúng. "Responsibility" (n), "responsibly" (adv), "respond" (v) đều sai cấu trúc.'},
{id:'wf12',cat:'Word Form',s:'The new policy will _____ take effect from January 1st.',o:['A) official','B) officially','C) officiate','D) officials'],a:1,e:'Trước động từ nguyên thể "take effect" cần TRẠNG TỪ. "Officially" (adv) = một cách chính thức là đúng. "Official" (adj), "officiate" (v), "officials" (n số nhiều) đều sai.'},
{id:'wf13',cat:'Word Form',s:'The training program improved employee _____ significantly.',o:['A) produce','B) productive','C) productivity','D) productively'],a:2,e:'Sau động từ "improved" cần DANH TỪ làm tân ngữ. "Productivity" (n) = năng suất là đúng. "Produce" (v/n) = sản xuất, "productive" (adj), "productively" (adv) đều sai vị trí.'},
{id:'wf14',cat:'Word Form',s:'The results of the survey were quite _____.',o:['A) encourage','B) encouraged','C) encouraging','D) encouragement'],a:2,e:'Sau động từ "were" cần TÍNH TỪ bổ ngữ. "Encouraging" (adj/phân từ hiện tại) = đáng khích lệ là đúng. Phân biệt: "encouraging" (gây cảm giác tích cực) ≠ "encouraged" (cảm thấy được khích lệ — dùng cho người).'},
{id:'wf15',cat:'Word Form',s:'The company made a _____ to reduce its carbon footprint.',o:['A) commit','B) commitment','C) committed','D) committing'],a:1,e:'Sau mạo từ "a" cần DANH TỪ đếm được số ít. "Commitment" (n) = cam kết là đúng. "Commit" (v), "committed" (adj), "committing" (v-ing) đều không phù hợp sau mạo từ.'},
{id:'wf16',cat:'Word Form',s:'She was _____ recognized for her outstanding contribution.',o:['A) public','B) publicize','C) publicly','D) publication'],a:2,e:'Trước tính từ "recognized" cần TRẠNG TỪ. "Publicly" (adv) = công khai là đúng. "Public" (adj/n), "publicize" (v), "publication" (n) không thể bổ nghĩa cho tính từ/động từ.'},
{id:'wf17',cat:'Word Form',s:'The board is seeking a _____ candidate for the CEO position.',o:['A) quality','B) qualify','C) qualified','D) qualification'],a:2,e:'Trước danh từ "candidate" cần TÍNH TỪ. "Qualified" (adj) = có đủ năng lực, đủ tiêu chuẩn là đúng. "Quality" (n/adj nhưng nghĩa khác), "qualify" (v), "qualification" (n).'},
{id:'wf18',cat:'Word Form',s:'The _____ between the two companies lasted for over a decade.',o:['A) partner','B) partnering','C) partnership','D) partnered'],a:2,e:'Sau mạo từ "The" cần DANH TỪ làm chủ ngữ. "Partnership" (n) = quan hệ đối tác là đúng. "Partner" (n/v) = đối tác/hợp tác, "partnering" (v-ing), "partnered" (adj/v).'},
{id:'wf19',cat:'Word Form',s:'The manager spoke _____ about the upcoming layoffs.',o:['A) honest','B) honesty','C) dishonest','D) honestly'],a:3,e:'Sau động từ "spoke" cần TRẠNG TỪ. "Honestly" (adv) = thành thật là đúng. "Honest" (adj), "honesty" (n), "dishonest" (adj) = không trung thực (nghĩa ngược).'},
{id:'wf20',cat:'Word Form',s:'Staff will receive a _____ bonus at the end of the fiscal year.',o:['A) performance','B) perform','C) performed','D) performer'],a:0,e:'Trước danh từ "bonus" cần DANH TỪ/TÍNH TỪ bổ nghĩa. "Performance" (n) dùng như tính từ bổ nghĩa = thưởng theo hiệu suất (performance bonus) là đúng. "Perform" (v), "performed" (v quá khứ), "performer" (n = diễn viên).'},
// ── VERB TENSE (10) ─────────────────────────────────────────────
{id:'vt01',cat:'Verb Tense',s:'By the time the CEO arrived, the board _____ the decision already.',o:['A) made','B) has made','C) had made','D) was making'],a:2,e:'Dùng THÌ QUÁ KHỨ HOÀN THÀNH (had + V3) khi hành động xảy ra TRƯỚC một hành động quá khứ khác. "The CEO arrived" là mốc quá khứ → quyết định được đưa ra TRƯỚC đó → "had made" là đúng.'},
{id:'vt02',cat:'Verb Tense',s:'The company _____ a new branch in Ho Chi Minh City next year.',o:['A) opens','B) opened','C) will open','D) open'],a:2,e:'Dùng THÌ TƯƠNG LAI ĐƠN (will + V) cho kế hoạch hoặc dự định trong tương lai. "Next year" là dấu hiệu của tương lai → "will open" là đúng.'},
{id:'vt03',cat:'Verb Tense',s:'She _____ for this company since she graduated from university.',o:['A) worked','B) works','C) has worked','D) had worked'],a:2,e:'Dùng THÌ HIỆN TẠI HOÀN THÀNH (has/have + V3) cho hành động bắt đầu trong quá khứ và vẫn còn tiếp diễn đến hiện tại. "Since she graduated" cho thấy liên tục từ quá khứ đến nay → "has worked" là đúng.'},
{id:'vt04',cat:'Verb Tense',s:'The report was being _____ when the power went out.',o:['A) print','B) printed','C) printing','D) prints'],a:1,e:'THÌ QUÁ KHỨ BỊ ĐỘNG TIẾP DIỄN (was/were being + V3) diễn tả hành động đang xảy ra (bị động) tại một thời điểm trong quá khứ. "When the power went out" cho thấy hành động đang diễn ra → "was being printed" là đúng.'},
{id:'vt05',cat:'Verb Tense',s:'If we reduce costs now, we _____ higher profits next quarter.',o:['A) see','B) saw','C) will see','D) have seen'],a:2,e:'Câu ĐIỀU KIỆN LOẠI 1 (điều kiện có thể xảy ra): If + thì hiện tại đơn, will + V. "If we reduce costs" → kết quả: "we will see higher profits" là đúng.'},
{id:'vt06',cat:'Verb Tense',s:'The annual conference _____ every year in Singapore.',o:['A) held','B) is held','C) has held','D) was held'],a:1,e:'Dùng THÌ HIỆN TẠI BỊ ĐỘNG (am/is/are + V3) cho sự kiện xảy ra định kỳ/thường xuyên ở dạng bị động. "Every year" là dấu hiệu thì hiện tại đơn → "is held" là đúng.'},
{id:'vt07',cat:'Verb Tense',s:'We _____ the client for three hours before reaching an agreement.',o:['A) negotiate','B) were negotiating','C) had been negotiating','D) will negotiate'],a:2,e:'Dùng THÌ QUÁ KHỨ HOÀN THÀNH TIẾP DIỄN (had been + V-ing) nhấn mạnh hành động kéo dài liên tục TRƯỚC một thời điểm trong quá khứ. "For three hours before reaching an agreement" → "had been negotiating" là đúng.'},
{id:'vt08',cat:'Verb Tense',s:'The team _____ on the project when the manager called.',o:['A) worked','B) was working','C) has worked','D) works'],a:1,e:'Dùng THÌ QUÁ KHỨ TIẾP DIỄN (was/were + V-ing) cho hành động ĐANG XẢY RA tại một thời điểm trong quá khứ. "When the manager called" là thời điểm cụ thể → "was working" là đúng.'},
{id:'vt09',cat:'Verb Tense',s:'The new regulations _____ effect from the first of next month.',o:['A) takes','B) took','C) will take','D) take'],a:2,e:'Dùng THÌ TƯƠNG LAI ĐƠN (will + V) cho sự kiện được lên kế hoạch trong tương lai. "From the first of next month" → "will take" là đúng.'},
{id:'vt10',cat:'Verb Tense',s:'By 2030, the company _____ its revenue by 50 percent.',o:['A) doubles','B) doubled','C) will have doubled','D) has doubled'],a:2,e:'Dùng THÌ TƯƠNG LAI HOÀN THÀNH (will have + V3) cho hành động sẽ hoàn thành TRƯỚC một thời điểm trong tương lai. "By 2030" là mốc tương lai → "will have doubled" là đúng.'},
// ── PASSIVE VOICE (10) ──────────────────────────────────────────
{id:'pv01',cat:'Passive Voice',s:'The annual budget _____ by the board of directors last Monday.',o:['A) approved','B) was approved','C) has approved','D) is approving'],a:1,e:'Dùng BỊ ĐỘNG THÌ QUÁ KHỨ ĐƠN (was/were + V3) khi chủ thể bị tác động trong quá khứ. "Last Monday" là dấu hiệu quá khứ, chủ ngữ "budget" là vật được phê duyệt → "was approved" là đúng.'},
{id:'pv02',cat:'Passive Voice',s:'All applications _____ online before the deadline.',o:['A) must submit','B) must be submitted','C) must be submitting','D) must have submitted'],a:1,e:'Dùng MODAL + BỊ ĐỘNG (must be + V3) cho nghĩa vụ bị động. "Applications" là chủ ngữ chịu tác động, không phải người thực hiện → "must be submitted" là đúng. "Must submit" là chủ động (chủ ngữ tự nộp).'},
{id:'pv03',cat:'Passive Voice',s:'The new office building _____ currently by a local firm.',o:['A) designs','B) is being designed','C) has designed','D) designed'],a:1,e:'Dùng HIỆN TẠI TIẾP DIỄN BỊ ĐỘNG (is being + V3) cho hành động đang xảy ra ở thời điểm nói, dạng bị động. "Currently" là dấu hiệu → "is being designed" là đúng.'},
{id:'pv04',cat:'Passive Voice',s:'Employees _____ to report any safety concerns immediately.',o:['A) encourage','B) are encouraged','C) have encouraged','D) encouraging'],a:1,e:'Dùng HIỆN TẠI ĐƠN BỊ ĐỘNG (am/is/are + V3) cho quy định/chính sách chung. "Employees" = số nhiều → "are encouraged" là đúng. Lưu ý: "encourage somebody to do" → bị động: "be encouraged to do".'},
{id:'pv05',cat:'Passive Voice',s:'The damaged goods _____ to the supplier for a full refund.',o:['A) returned','B) were returned','C) returning','D) had returning'],a:1,e:'Dùng QUÁ KHỨ ĐƠN BỊ ĐỘNG (was/were + V3). "The damaged goods" là chủ ngữ bị tác động, hành động trong quá khứ → "were returned" là đúng.'},
{id:'pv06',cat:'Passive Voice',s:'New safety procedures _____ after last year\'s incident.',o:['A) introduce','B) have been introduced','C) introduced','D) are introducing'],a:1,e:'Dùng HIỆN TẠI HOÀN THÀNH BỊ ĐỘNG (have been + V3) nhấn mạnh kết quả kéo dài đến hiện tại. Thủ tục đã được áp dụng và vẫn còn hiệu lực → "have been introduced" là đúng.'},
{id:'pv07',cat:'Passive Voice',s:'The merger _____ by the time we receive shareholder approval.',o:['A) will complete','B) will have been completed','C) completes','D) completed'],a:1,e:'Dùng TƯƠNG LAI HOÀN THÀNH BỊ ĐỘNG (will have been + V3) cho hành động sẽ hoàn thành trước mốc tương lai. "By the time we receive approval" là mốc tương lai → "will have been completed" là đúng.'},
{id:'pv08',cat:'Passive Voice',s:'The documents need _____ before they can be sent out.',o:['A) sign','B) signed','C) to be signed','D) signing'],a:2,e:'Cấu trúc "need + to be + V3" = cần được làm gì. "The documents" là chủ ngữ cần được ký → "to be signed" là đúng. Lưu ý: "need + V-ing" cũng có nghĩa tương tự nhưng ở đây đáp án A cho sẵn "to be signed".'},
{id:'pv09',cat:'Passive Voice',s:'Our products _____ to over 30 countries worldwide.',o:['A) export','B) are exported','C) exporting','D) have exporting'],a:1,e:'Dùng HIỆN TẠI ĐƠN BỊ ĐỘNG (are + V3) cho sự thật chung/thói quen. "Our products" là số nhiều, là vật được xuất khẩu → "are exported" là đúng.'},
{id:'pv10',cat:'Passive Voice',s:'The conference room _____ while repairs are underway.',o:['A) cannot use','B) cannot be used','C) not used','D) does not use'],a:1,e:'Dùng MODAL + BỊ ĐỘNG phủ định (cannot be + V3) cho sự cấm đoán. "The conference room" là chủ ngữ không thể được sử dụng → "cannot be used" là đúng.'},
// ── PREPOSITIONS (10) ────────────────────────────────────────────
{id:'pr01',cat:'Prepositions',s:'She is responsible _____ managing the entire project team.',o:['A) of','B) for','C) with','D) about'],a:1,e:'Collocation cố định: "responsible FOR" = chịu trách nhiệm về. Đây là cặp giới từ bắt buộc phải học thuộc. Các cặp tương tự: "accountable for", "liable for".'},
{id:'pr02',cat:'Prepositions',s:'The meeting has been rescheduled _____ next Thursday.',o:['A) in','B) on','C) at','D) to'],a:3,e:'"Reschedule TO" = dời lịch sang (thời điểm mới). Phân biệt: "reschedule to Friday" (chuyển sang thứ Sáu) vs "postpone until Friday" (hoãn đến thứ Sáu). "To" dùng khi chỉ điểm đến mới.'},
{id:'pr03',cat:'Prepositions',s:'Please refer _____ the attached file for further information.',o:['A) at','B) with','C) to','D) in'],a:2,e:'"Refer TO" = tham khảo, đề cập đến. Đây là phrasal verb cố định. Các cụm tương tự: "look at", "turn to", "consult". Luôn dùng "to" sau "refer".'},
{id:'pr04',cat:'Prepositions',s:'The store will be closed _____ renovation until further notice.',o:['A) for','B) due to','C) because','D) despite'],a:1,e:'"Due TO + danh từ/cụm danh từ" = do, vì (nguyên nhân). Phân biệt: "due to" + noun phrase, "because" + mệnh đề (because + S + V). "For renovation" cũng đúng ngữ pháp nhưng "due to renovation" nhấn mạnh nguyên nhân hơn.'},
{id:'pr05',cat:'Prepositions',s:'We are looking forward _____ hearing from you soon.',o:['A) to','B) for','C) at','D) of'],a:0,e:'"Look forward TO + V-ing" = mong chờ. "To" ở đây là GIỚI TỪ, không phải "to" nguyên thể → sau đó phải dùng V-ing, không dùng V nguyên thể. Đây là lỗi rất phổ biến trong TOEIC.'},
{id:'pr06',cat:'Prepositions',s:'The CEO will be _____ vacation from June 10 to 20.',o:['A) in','B) at','C) on','D) for'],a:2,e:'"On vacation" = đang nghỉ phép. Collocation cố định trong tiếng Anh Mỹ. Trong tiếng Anh Anh dùng "on holiday". Phân biệt: "on vacation" (đang đi), "for a vacation" (để đi nghỉ).'},
{id:'pr07',cat:'Prepositions',s:'The invoice must be paid _____ 30 days of receipt.',o:['A) in','B) within','C) after','D) on'],a:1,e:'"Within + khoảng thời gian" = trong vòng, không quá. "Within 30 days" = trong vòng 30 ngày (tức là phải làm trước khi 30 ngày kết thúc). Phân biệt: "in 30 days" = sau 30 ngày nữa.'},
{id:'pr08',cat:'Prepositions',s:'The company has been operating _____ over 50 years.',o:['A) since','B) for','C) during','D) from'],a:1,e:'"For + khoảng thời gian" = trong (suốt) bao lâu. "For over 50 years" = trong hơn 50 năm. Phân biệt: "since" + điểm thời gian cụ thể (since 1970), "for" + khoảng thời gian (for 50 years).'},
{id:'pr09',cat:'Prepositions',s:'All staff should comply _____ the new dress code policy.',o:['A) to','B) at','C) for','D) with'],a:3,e:'"Comply WITH" = tuân thủ. Collocation bắt buộc trong TOEIC. Các cụm tương tự: "agree with", "deal with", "meet with". Luôn ghi nhớ: comply + WITH.'},
{id:'pr10',cat:'Prepositions',s:'The product was developed _____ response to customer demand.',o:['A) as','B) in','C) at','D) with'],a:1,e:'"In response TO" = để đáp lại, để phản hồi. Đây là cụm giới từ cố định (fixed prepositional phrase). Tương tự: "in reaction to", "in reply to", "in answer to".'},
// ── CONJUNCTIONS (10) ────────────────────────────────────────────
{id:'cj01',cat:'Conjunctions',s:'_____ the budget was limited, the team completed the project on time.',o:['A) However','B) Despite','C) Although','D) Even so'],a:2,e:'"Although/Even though/Though + mệnh đề (S+V)" = mặc dù. "Despite/In spite of + danh từ/V-ing" = mặc dù. Câu này có S+V ("the budget was limited") → cần liên từ → "Although" là đúng. "Despite" chỉ đi với danh từ/V-ing.'},
{id:'cj02',cat:'Conjunctions',s:'We will proceed with the launch _____ all requirements are met.',o:['A) only if','B) in spite of','C) so that','D) even though'],a:0,e:'"Only if" = chỉ khi, chỉ với điều kiện là. Nhấn mạnh điều kiện duy nhất. "In spite of" + noun phrase (không phải mệnh đề). "So that" = để mà. "Even though" = mặc dù (ngược nghĩa).'},
{id:'cj03',cat:'Conjunctions',s:'The company expanded rapidly, _____ it faced financial difficulties.',o:['A) and','B) yet','C) so','D) for'],a:1,e:'"Yet" (liên từ kết hợp) = thế nhưng, vậy mà. Diễn tả sự tương phản bất ngờ giữa hai ý. Tương tự "but" nhưng nhấn mạnh hơn. Câu này: mở rộng nhanh NHƯNG lại gặp khó khăn tài chính.'},
{id:'cj04',cat:'Conjunctions',s:'Please notify us _____ you will be absent from the training.',o:['A) so that','B) because','C) if','D) although'],a:2,e:'"If" = nếu, dùng cho điều kiện. Câu này: "nếu bạn sẽ vắng mặt, hãy thông báo". "So that" = để mà, "because" = bởi vì (không phải điều kiện), "although" = mặc dù.'},
{id:'cj05',cat:'Conjunctions',s:'The store will stay open late _____ customers can finish shopping.',o:['A) even though','B) so that','C) provided that','D) as long as'],a:1,e:'"So that + S + can/will + V" = để mà, nhằm mục đích. Diễn tả mục đích. Câu này: cửa hàng mở cửa muộn ĐỂ khách hàng có thể mua sắm xong. "Even though" = mặc dù, "provided that" = miễn là (điều kiện).'},
{id:'cj06',cat:'Conjunctions',s:'_____ being new to the job, she performed exceptionally well.',o:['A) Although','B) Despite','C) However','D) Even though'],a:1,e:'"Despite + danh từ/V-ing" = mặc dù (theo sau phải là danh từ, không phải mệnh đề). "Being new to the job" là V-ing phrase → "Despite" là đúng. "Although/Even though" cần S+V theo sau.'},
{id:'cj07',cat:'Conjunctions',s:'The project was approved _____ the initial budget concerns.',o:['A) because of','B) despite','C) although','D) so'],a:1,e:'"Despite + danh từ" = mặc dù. "Initial budget concerns" là cụm danh từ → "despite" là đúng. "Although + S+V" (không phải danh từ), "because of + danh từ" = vì (nguyên nhân, không phải tương phản).'},
{id:'cj08',cat:'Conjunctions',s:'You must submit your application _____ you wish to be considered.',o:['A) otherwise','B) in case','C) if','D) as though'],a:2,e:'"If + S + V" = nếu, điều kiện. "You wish to be considered" là điều kiện để được xét duyệt. "Otherwise" = nếu không, "in case" = phòng khi, "as though" = như thể.'},
{id:'cj09',cat:'Conjunctions',s:'She studied hard for the exam; _____, she passed with distinction.',o:['A) however','B) therefore','C) although','D) despite'],a:1,e:'"Therefore" (trạng từ liên kết) = do đó, vì vậy. Dùng sau dấu chấm phẩy (;) hoặc dấu chấm để nối hai câu độc lập, thể hiện kết quả. "However" = tuy nhiên (tương phản), "although" = mặc dù (nhượng bộ).'},
{id:'cj10',cat:'Conjunctions',s:'The factory operates 24 hours a day _____ demand remains high.',o:['A) so that','B) as long as','C) in order to','D) despite'],a:1,e:'"As long as" = miễn là, chừng nào còn. Diễn tả điều kiện kéo dài. "So that" = để mà (mục đích), "in order to" + V nguyên thể (mục đích), "despite" + danh từ (tương phản).'},
// ── PRONOUNS & DETERMINERS (5) ───────────────────────────────────
{id:'pd01',cat:'Pronouns',s:'_____ employee is expected to complete the training by Friday.',o:['A) All','B) Every','C) Many','D) Several'],a:1,e:'"Every + danh từ số ÍT + động từ số ÍT" = mỗi, từng (dùng với danh từ đếm được số ít). "Every employee IS expected..." → đúng. "All + danh từ số NHIỀU" = tất cả. "Many/Several" = nhiều (không dùng với danh từ số ít).'},
{id:'pd02',cat:'Pronouns',s:'The clients expressed _____ satisfaction with our services.',o:['A) they','B) their','C) them','D) themselves'],a:1,e:'Sau chủ ngữ "The clients" cần ĐẠI TỪ SỞ HỮU bổ nghĩa cho "satisfaction". "Their" (tính từ sở hữu) = của họ là đúng. "They" (chủ ngữ), "them" (tân ngữ), "themselves" (phản thân) đều sai vị trí.'},
{id:'pd03',cat:'Pronouns',s:'The two proposals are similar, but _____ has unique advantages.',o:['A) all','B) each','C) every','D) much'],a:1,e:'"Each" dùng để chỉ từng cái trong nhóm hai hoặc nhiều hơn, nhấn mạnh tính riêng biệt. "Each has unique advantages" = mỗi cái đều có ưu điểm riêng. "All" = tất cả (số nhiều), "every" + số ít, "much" = nhiều (không đếm được).'},
{id:'pd04',cat:'Pronouns',s:'Please send the report to Mr. Tran or _____ assistant.',o:['A) him','B) he','C) his','D) himself'],a:2,e:'Trước danh từ "assistant" cần TÍNH TỪ SỞ HỮU. "His assistant" = trợ lý của ông ấy (chỉ Mr. Tran). "Him" (tân ngữ), "he" (chủ ngữ), "himself" (phản thân) đều không thể đứng trước danh từ.'},
{id:'pd05',cat:'Pronouns',s:'The management team completed the restructuring _____ without any outside help.',o:['A) them','B) their','C) themselves','D) they'],a:2,e:'"Themselves" là đại từ phản thân, dùng nhấn mạnh chủ ngữ "The management team" tự hoàn thành mà không cần trợ giúp. "Them" (tân ngữ thông thường), "their" (tính từ sở hữu), "they" (chủ ngữ).'},
// ── COMPARISON (5) ───────────────────────────────────────────────
{id:'cp01',cat:'Comparison',s:'Our new model is far _____ than the previous version.',o:['A) reliable','B) more reliable','C) most reliable','D) reliably'],a:1,e:'Tính từ dài (3 âm tiết trở lên) dùng "more + adj + than" để so sánh hơn. "More reliable than" = đáng tin cậy hơn. "Far more" nhấn mạnh mức độ chênh lệch lớn. "Most reliable" = so sánh nhất.'},
{id:'cp02',cat:'Comparison',s:'This quarter\'s results are _____ we had expected.',o:['A) better than','B) the best than','C) well than','D) more good than'],a:0,e:'"Good" có dạng SO SÁNH HƠN BẤT QUY TẮC là "better". "Better than" = tốt hơn là đúng. "The best" là so sánh nhất (không dùng với "than"), "well" là trạng từ, "more good" không tồn tại.'},
{id:'cp03',cat:'Comparison',s:'The _____ you invest early, the more you will gain in the long run.',o:['A) many','B) more','C) most','D) much'],a:1,e:'CẤU TRÚC "The + so sánh hơn..., the + so sánh hơn..." = càng... càng... "The more you invest..., the more you will gain" là cấu trúc cố định. "Many/most/much" không dùng trong cấu trúc này.'},
{id:'cp04',cat:'Comparison',s:'Our customer service is _____ in the industry.',o:['A) better','B) good','C) best','D) the best'],a:3,e:'SO SÁNH NHẤT (the + adj + est hoặc the most + adj) dùng khi so sánh với tất cả trong nhóm. "In the industry" = trong toàn ngành → dùng so sánh nhất. "The best" là đúng. "Better" chỉ so sánh hơn.'},
{id:'cp05',cat:'Comparison',s:'The second branch is twice _____ the first one.',o:['A) as large as','B) larger than','C) the largest','D) large than'],a:0,e:'CẤU TRÚC BỘI SỐ: "twice/three times + as + adj + as" = gấp đôi/ba lần. "Twice as large as" = lớn gấp đôi là đúng. KHÔNG nói "twice larger than" (sai trong chuẩn ngữ pháp). "Larger than" = lớn hơn (không có bội số).'},
// ── MODAL VERBS (10) ─────────────────────────────────────────────
{id:'mv01',cat:'Modal Verbs',s:'Employees _____ carry their ID badges at all times.',o:['A) can','B) must','C) might','D) would'],a:1,e:'"Must" diễn tả NGHĨA VỤ BẮT BUỘC, quy định không thể tránh. "Employees must carry ID badges" = nhân viên bắt buộc phải đeo thẻ. "Can" = có thể (khả năng), "might" = có lẽ (khả năng thấp), "would" = sẽ (lịch sự/điều kiện).'},
{id:'mv02',cat:'Modal Verbs',s:'You _____ bring your passport to the interview tomorrow.',o:['A) might','B) could','C) should','D) shall'],a:2,e:'"Should" diễn tả LỜI KHUYÊN hoặc KHUYẾN NGHỊ. "You should bring your passport" = bạn nên mang hộ chiếu (lời khuyên). "Might" = có thể, "could" = có thể (khả năng), "shall" = sẽ (trang trọng/đề xuất).'},
{id:'mv03',cat:'Modal Verbs',s:'The shipment _____ arrive by Friday at the latest.',o:['A) ought to','B) will','C) shall','D) can'],a:0,e:'"Ought to" = nên, được mong đợi (tương tự "should" nhưng có hàm ý trách nhiệm đạo đức hơn). "The shipment ought to arrive" = lô hàng được kỳ vọng sẽ đến. Dùng phổ biến trong văn viết trang trọng.'},
{id:'mv04',cat:'Modal Verbs',s:'We _____ call you back as soon as a decision has been made.',o:['A) must','B) shall','C) will','D) ought'],a:2,e:'"Will" diễn tả CAM KẾT hoặc QUYẾT TÂM trong tương lai. "We will call you back" = chúng tôi cam kết sẽ gọi lại. "Must" = phải (nghĩa vụ), "shall" = cách diễn đạt cổ điển, "ought" không đủ dạng (thiếu "to").'},
{id:'mv05',cat:'Modal Verbs',s:'_____ you please send me the updated contract by email?',o:['A) Would','B) Must','C) Shall','D) Should'],a:0,e:'"Would you please...?" là cách YÊU CẦU LỊCH SỰ nhất trong giao tiếp kinh doanh. "Could you please...?" cũng lịch sự. "Must" = ra lệnh (không lịch sự), "shall/should" thường dùng đề xuất, không phải yêu cầu.'},
{id:'mv06',cat:'Modal Verbs',s:'The candidate _____ have submitted her application last week.',o:['A) must','B) should','C) would','D) could'],a:1,e:'"Should have + V3" dien ta CHI TRICH ve viec KHONG LAM trong qua khu. "She should have submitted" = le ra co ay phai nop don nhung da khong nop. "Must have + V3" = chac han da (suy luan).'},
{id:'mv07',cat:'Modal Verbs',s:'You _____ leave early today as all your tasks are done.',o:['A) must','B) might','C) may','D) shall'],a:2,e:'"May" diễn tả SỰ CHO PHÉP trong văn phong trang trọng. "You may leave early" = bạn được phép về sớm. "Must" = bắt buộc, "might" = có lẽ (khả năng), "shall" = sẽ (trang trọng, thường ở ngôi 1).'},
{id:'mv08',cat:'Modal Verbs',s:'The merger _____ be announced before the end of this month.',o:['A) should','B) might','C) will','D) must'],a:1,e:'"Might" dien ta KHA NANG KHONG CHAC CHAN (thap hon "may"). Might be announced = co the se duoc thong bao (khong chac chan). "Should" = nen/duoc ky vong, "will" = chac chan se.'},
{id:'mv09',cat:'Modal Verbs',s:'Staff _____ not use company equipment for personal purposes.',o:['A) should','B) may','C) would','D) can'],a:0,e:'"Should not" diễn tả ĐIỀU KHÔNG NÊN LÀM, quy định/chính sách. "Staff should not use company equipment for personal purposes" = nhân viên không nên/không được phép sử dụng. Phù hợp ngữ cảnh chính sách công ty.'},
{id:'mv10',cat:'Modal Verbs',s:'The new regulation _____ have a significant impact on our business.',o:['A) ought','B) could','C) should','D) shall'],a:1,e:'"Could" diễn tả KHẢ NĂNG CÓ THỂ XẢY RA trong tương lai. "The new regulation could have an impact" = quy định mới CÓ THỂ ảnh hưởng (không chắc chắn). "Ought" thiếu "to", "should" = được kỳ vọng (chắc hơn), "shall" = trang trọng.'},
// ── NEW GRAMMAR QUESTIONS (80 more → total ~160) ──────────────────

// WORD FORM - 15 more
{id:'wf21',cat:'Word Form',s:'The new manager showed great _____ in handling the crisis.',o:['A) lead','B) leader','C) leadership','D) leading'],a:2,e:'"Leadership" (n) = khả năng lãnh đạo, theo sau "great" cần danh từ. "Lead" (v/n), "leader" (n = người lãnh đạo, không phải kỹ năng), "leading" (adj/v).'},
{id:'wf22',cat:'Word Form',s:'All staff must wear _____ clothing when entering the laboratory.',o:['A) protect','B) protection','C) protective','D) protectively'],a:2,e:'"Protective" (adj) = bảo hộ, đứng trước danh từ "clothing". "Protect" (v), "protection" (n), "protectively" (adv).'},
{id:'wf23',cat:'Word Form',s:'The report revealed several _____ in the accounting system.',o:['A) irregular','B) irregularity','C) irregularities','D) irregularly'],a:2,e:'"Irregularities" (n số nhiều) = những bất thường. Sau "several" cần danh từ số nhiều. "Irregular" (adj), "irregularity" (n số ít).'},
{id:'wf24',cat:'Word Form',s:'We need to _____ our marketing strategy to reach younger customers.',o:['A) revision','B) revise','C) revised','D) revisionary'],a:1,e:'"Revise" (v) = sửa đổi, sau "need to" cần động từ nguyên thể. "Revision" (n), "revised" (adj/v quá khứ).'},
{id:'wf25',cat:'Word Form',s:'The _____ of the new product line was carefully planned.',o:['A) introduce','B) introduction','C) introductory','D) introduced'],a:1,e:'"Introduction" (n) = sự giới thiệu, là chủ ngữ của câu. "Introduce" (v), "introductory" (adj), "introduced" (v quá khứ).'},
{id:'wf26',cat:'Word Form',s:'She handled the complaint with remarkable _____ and patience.',o:['A) profession','B) professional','C) professionally','D) professionalism'],a:3,e:'"Professionalism" (n) = tính chuyên nghiệp, song song với "patience" (cũng là danh từ). "Profession" (n = nghề nghiệp), "professional" (adj/n).'},
{id:'wf27',cat:'Word Form',s:'The company made a _____ decision to expand into Asian markets.',o:['A) strategy','B) strategize','C) strategic','D) strategically'],a:2,e:'"Strategic" (adj) = mang tính chiến lược, bổ nghĩa cho danh từ "decision". "Strategy" (n), "strategize" (v), "strategically" (adv).'},
{id:'wf28',cat:'Word Form',s:'The board voted _____ to approve the merger.',o:['A) unanimous','B) unanimously','C) unanimity','D) unanimousness'],a:1,e:'"Unanimously" (adv) = nhất trí, bổ nghĩa cho động từ "voted". "Unanimous" (adj).'},
{id:'wf29',cat:'Word Form',s:'Please confirm your _____ at least 24 hours before the meeting.',o:['A) attend','B) attendant','C) attendance','D) attending'],a:2,e:'"Attendance" (n) = sự tham dự, sau "your" cần danh từ. "Attend" (v), "attendant" (n = nhân viên phục vụ), "attending" (adj/v-ing).'},
{id:'wf30',cat:'Word Form',s:'The new policy will _____ all employees to submit monthly reports.',o:['A) require','B) requirement','C) required','D) requiring'],a:0,e:'"Require" (v) = yêu cầu, sau "will" cần động từ nguyên thể. "Requirement" (n), "required" (adj/v quá khứ).'},
{id:'wf31',cat:'Word Form',s:'There has been a significant _____ in customer satisfaction this year.',o:['A) improve','B) improved','C) improvement','D) improving'],a:2,e:'"Improvement" (n) = sự cải thiện, sau "a significant" cần danh từ đếm được số ít. "Improve" (v), "improved" (adj), "improving" (adj/v-ing).'},
{id:'wf32',cat:'Word Form',s:'The CEO gave a very _____ speech about the company\'s future plans.',o:['A) detail','B) detailed','C) detailing','D) details'],a:1,e:'"Detailed" (adj) = chi tiết, bổ nghĩa cho danh từ "speech". "Detail" (n/v), "details" (n số nhiều).'},
{id:'wf33',cat:'Word Form',s:'The new software will greatly _____ the efficiency of our operations.',o:['A) enhance','B) enhancement','C) enhanced','D) enhancing'],a:0,e:'"Enhance" (v) = nâng cao, sau "will greatly" cần động từ nguyên thể. "Enhancement" (n), "enhanced" (adj/v quá khứ).'},
{id:'wf34',cat:'Word Form',s:'All _____ must be submitted along with the completed application form.',o:['A) document','B) documentary','C) documents','D) documentation'],a:2,e:'"Documents" (n số nhiều) = các tài liệu, phù hợp với "All" và động từ số nhiều "must be submitted". "Documentation" (n không đếm được = bộ tài liệu tổng thể).'},
{id:'wf35',cat:'Word Form',s:'The seminar provided valuable _____ on the latest industry trends.',o:['A) inform','B) information','C) informative','D) informed'],a:1,e:'"Information" (n không đếm được) = thông tin, sau "valuable" cần danh từ. "Inform" (v), "informative" (adj = có nhiều thông tin), "informed" (adj = được thông báo).'},

// VERB TENSE - 10 more
{id:'vt11',cat:'Verb Tense',s:'The company _____ in this industry for over two decades.',o:['A) operates','B) operated','C) has been operating','D) had operated'],a:2,e:'Hiện tại hoàn thành tiếp diễn (has been + V-ing) nhấn mạnh hoạt động liên tục từ quá khứ đến hiện tại. "For over two decades" là khoảng thời gian kéo dài đến nay.'},
{id:'vt12',cat:'Verb Tense',s:'By next Friday, the team _____ the project proposal.',o:['A) will finish','B) will have finished','C) finishes','D) finished'],a:1,e:'Tương lai hoàn thành (will have + V3) cho hành động sẽ hoàn thành trước một mốc tương lai. "By next Friday" là mốc tương lai.'},
{id:'vt13',cat:'Verb Tense',s:'We _____ the client\'s office when the deal was finalized.',o:['A) visit','B) were visiting','C) had visited','D) have visited'],a:1,e:'Quá khứ tiếp diễn (was/were + V-ing) cho hành động đang xảy ra tại một thời điểm trong quá khứ. "When the deal was finalized" là thời điểm cụ thể.'},
{id:'vt14',cat:'Verb Tense',s:'Sales _____ by 20% since we launched the new campaign.',o:['A) increase','B) increased','C) have increased','D) had increased'],a:2,e:'Hiện tại hoàn thành (have + V3) khi hành động bắt đầu trong quá khứ và kết quả vẫn liên quan đến hiện tại. "Since" là dấu hiệu của thì này.'},
{id:'vt15',cat:'Verb Tense',s:'The manager _____ the report before leaving the office yesterday.',o:['A) reviews','B) reviewed','C) has reviewed','D) had reviewed'],a:3,e:'Quá khứ hoàn thành (had + V3) cho hành động xảy ra TRƯỚC một thời điểm quá khứ khác. "Before leaving" → đánh giá xong TRƯỚC KHI rời văn phòng.'},
{id:'vt16',cat:'Verb Tense',s:'We _____ the new office building next month.',o:['A) moved into','B) move into','C) are moving into','D) have moved into'],a:2,e:'Hiện tại tiếp diễn (am/is/are + V-ing) dùng cho kế hoạch tương lai đã được sắp xếp cụ thể. "Next month" + kế hoạch cụ thể → hiện tại tiếp diễn là tự nhiên nhất.'},
{id:'vt17',cat:'Verb Tense',s:'The factory _____ 500 units per day before the new machines arrived.',o:['A) produces','B) produced','C) was producing','D) had been producing'],a:3,e:'Quá khứ hoàn thành tiếp diễn (had been + V-ing) nhấn mạnh hoạt động kéo dài liên tục TRƯỚC một mốc quá khứ. "Before the new machines arrived" là mốc quá khứ.'},
{id:'vt18',cat:'Verb Tense',s:'Look at those dark clouds! It _____ soon.',o:['A) rains','B) is going to rain','C) rained','D) has rained'],a:1,e:'"Be going to + V" dùng khi có bằng chứng trực tiếp cho thấy điều gì sắp xảy ra. "Look at those dark clouds" = bằng chứng trực tiếp → sắp mưa.'},
{id:'vt19',cat:'Verb Tense',s:'The contract _____ three times since it was first signed.',o:['A) renews','B) renewed','C) has been renewed','D) had been renewed'],a:2,e:'Hiện tại hoàn thành bị động (has been + V3) cho hành động xảy ra nhiều lần từ quá khứ đến nay. "Since it was first signed" → dùng hiện tại hoàn thành.'},
{id:'vt20',cat:'Verb Tense',s:'She _____ in the finance department for five years when she got promoted.',o:['A) works','B) worked','C) had been working','D) has been working'],a:2,e:'Quá khứ hoàn thành tiếp diễn (had been + V-ing) cho hành động kéo dài trước một sự kiện quá khứ. "When she got promoted" là mốc quá khứ → trước đó cô ấy đã làm được 5 năm.'},

// CONDITIONALS - 10 new
{id:'cd01',cat:'Conditionals',s:'If the weather _____ better tomorrow, we will hold the event outdoors.',o:['A) is','B) will be','C) would be','D) were'],a:0,e:'Điều kiện loại 1 (có thể xảy ra): If + hiện tại đơn, will + V. "Tomorrow" → khả năng thực tế → dùng hiện tại đơn trong mệnh đề if.'},
{id:'cd02',cat:'Conditionals',s:'If I _____ the CEO, I would invest more in employee training.',o:['A) am','B) was','C) were','D) will be'],a:2,e:'Điều kiện loại 2 (không có thật ở hiện tại): If + were (all subjects), would + V. "Were" dùng cho tất cả chủ ngữ trong điều kiện giả định.'},
{id:'cd03',cat:'Conditionals',s:'If the team _____ harder, they would have met the deadline.',o:['A) worked','B) had worked','C) works','D) would work'],a:1,e:'Điều kiện loại 3 (không có thật trong quá khứ): If + had + V3, would have + V3. Phê phán điều không xảy ra trong quá khứ.'},
{id:'cd04',cat:'Conditionals',s:'Unless you _____ the contract today, the offer will expire.',o:['A) sign','B) signed','C) will sign','D) would sign'],a:0,e:'"Unless" = "if not" → Unless + hiện tại đơn (điều kiện loại 1). "Unless you sign" = "If you do not sign".'},
{id:'cd05',cat:'Conditionals',s:'Had the manager been informed earlier, she _____ a better decision.',o:['A) makes','B) will make','C) would have made','D) made'],a:2,e:'Điều kiện loại 3 đảo ngữ: Had + S + V3 (= If + S + had + V3), would have + V3. "Had the manager been informed" = "If the manager had been informed".'},
{id:'cd06',cat:'Conditionals',s:'If you _____ any questions, please do not hesitate to contact us.',o:['A) have','B) had','C) will have','D) would have'],a:0,e:'Điều kiện loại 1 trong văn bản lịch sự: If + hiện tại đơn, mệnh lệnh cách. Đây là mẫu câu phổ biến trong email kinh doanh.'},
{id:'cd07',cat:'Conditionals',s:'The project _____ on time if we had received the budget approval earlier.',o:['A) completes','B) would complete','C) would have been completed','D) will complete'],a:2,e:'Điều kiện loại 3 bị động: would have been + V3. "If we had received" → kết quả phải là "would have been completed".'},
{id:'cd08',cat:'Conditionals',s:'Provided that all documents _____ in order, your visa will be approved.',o:['A) are','B) were','C) will be','D) would be'],a:0,e:'"Provided that" = "if" → điều kiện có thể xảy ra (loại 1) → hiện tại đơn. Đây là biểu thức điều kiện trang trọng dùng trong văn bản.'},
{id:'cd09',cat:'Conditionals',s:'Were the company to _____ its prices, it might lose customers.',o:['A) raise','B) raised','C) rising','D) be raised'],a:0,e:'Điều kiện loại 2 đảo ngữ trang trọng: "Were + S + to + V" = "If + S + were to + V". Thường gặp trong văn bản kinh doanh và báo cáo chính thức.'},
{id:'cd10',cat:'Conditionals',s:'If the report _____ submitted on time, we could have avoided the penalty.',o:['A) was','B) had been','C) were','D) would be'],a:1,e:'Điều kiện loại 3 bị động: If + had been + V3, could have + V3. "The report" là chủ thể bị động của "submit".'},

// RELATIVE CLAUSES - 10 new
{id:'rc01',cat:'Relative Clauses',s:'The candidate _____ resume impressed the panel was offered the job.',o:['A) who','B) whose','C) whom','D) which'],a:1,e:'"Whose" = đại từ quan hệ sở hữu, thay thế cho "the candidate\'s". "Whose resume" = "his/her resume". Phân biệt: "who" (chủ ngữ), "whom" (tân ngữ), "whose" (sở hữu).'},
{id:'rc02',cat:'Relative Clauses',s:'The office _____ we held the meeting was fully equipped.',o:['A) which','B) where','C) that','D) who'],a:1,e:'"Where" thay cho trạng từ chỉ nơi chốn. "The office where" = "the office in which". Phân biệt: "which/that" (thay thế danh từ), "where" (thay thế nơi chốn).'},
{id:'rc03',cat:'Relative Clauses',s:'The deadline, _____ was extended twice, is now set for next Monday.',o:['A) that','B) which','C) who','D) what'],a:1,e:'Mệnh đề quan hệ NON-RESTRICTIVE (có dấu phẩy) phải dùng "which", KHÔNG dùng "that". "That" chỉ dùng trong mệnh đề quan hệ restrictive (không có dấu phẩy).'},
{id:'rc04',cat:'Relative Clauses',s:'The employee _____ you interviewed yesterday has accepted the offer.',o:['A) who','B) whose','C) whom','D) which'],a:2,e:'"Whom" = tân ngữ của động từ, thay cho người. "You interviewed whom" → "the employee whom you interviewed". Trong văn nói có thể dùng "who", nhưng "whom" là đúng chuẩn.'},
{id:'rc05',cat:'Relative Clauses',s:'This is the reason _____ we decided to postpone the launch.',o:['A) that','B) which','C) why','D) when'],a:2,e:'"Why" thay cho "the reason". "The reason why" = "the reason for which". Phân biệt: "when" (thời gian), "where" (nơi chốn), "why" (lý do).'},
{id:'rc06',cat:'Relative Clauses',s:'The contract _____ was signed last year will expire soon.',o:['A) who','B) whom','C) which','D) whose'],a:2,e:'"Which" thay thế vật thể (contract). "Which was signed" = "that was signed". "Who/whom" chỉ dùng cho người.'},
{id:'rc07',cat:'Relative Clauses',s:'The year _____ the company went public was 2015.',o:['A) which','B) that','C) when','D) where'],a:2,e:'"When" thay cho "the year" (khoảng thời gian). "The year when" = "the year in which". Dùng "when" sau các danh từ chỉ thời gian: day, time, year, moment.'},
{id:'rc08',cat:'Relative Clauses',s:'She is the director _____ innovative ideas transformed the company.',o:['A) who','B) which','C) whose','D) whom'],a:2,e:'"Whose" = sở hữu. "The director whose ideas" = "the director and her ideas". Kiểm tra: nếu sau đại từ quan hệ là danh từ (không có "the") → "whose".'},
{id:'rc09',cat:'Relative Clauses',s:'All employees _____ work overtime will receive additional compensation.',o:['A) whom','B) who','C) which','D) whose'],a:1,e:'"Who" = chủ ngữ của mệnh đề quan hệ, thay cho người. "Employees who work" → "who" là chủ ngữ của "work". "Whom" chỉ dùng làm tân ngữ.'},
{id:'rc10',cat:'Relative Clauses',s:'The training program, _____ costs $500 per person, is highly recommended.',o:['A) that','B) what','C) which','D) who'],a:2,e:'Mệnh đề quan hệ non-restrictive (có dấu phẩy) → phải dùng "which". "What" không dùng trong relative clause. "That" không dùng sau dấu phẩy.'},

// ARTICLES - 10 new
{id:'ar01',cat:'Articles',s:'She has _____ MBA from Harvard Business School.',o:['A) a','B) an','C) the','D) no article'],a:1,e:'"An" dùng trước âm nguyên âm. "MBA" đọc là /em biː eɪ/ → bắt đầu bằng âm /e/ (nguyên âm) → "an MBA". Quy tắc: dựa vào ÂM THANH, không phải chữ cái.'},
{id:'ar02',cat:'Articles',s:'_____ information provided in the report was outdated.',o:['A) A','B) An','C) The','D) No article'],a:2,e:'"The" dùng khi người nghe/đọc biết rõ thông tin nào đang được nói đến. "The information provided in the report" = thông tin cụ thể đã được xác định bởi mệnh đề "provided in the report".'},
{id:'ar03',cat:'Articles',s:'We need to find _____ solution to this problem as soon as possible.',o:['A) a','B) an','C) the','D) no article'],a:0,e:'"A solution" = một giải pháp (chưa cụ thể). Dùng "a" vì đây là lần đầu đề cập và chưa xác định giải pháp nào. "The solution" sẽ dùng khi giải pháp đó đã được biết đến.'},
{id:'ar04',cat:'Articles',s:'_____ unemployment rate has risen significantly this quarter.',o:['A) A','B) An','C) The','D) No article'],a:2,e:'"The" dùng với các khái niệm duy nhất hoặc đã được biết đến chung. "The unemployment rate" = tỷ lệ thất nghiệp (chỉ có một tỷ lệ thất nghiệp trong bối cảnh đang nói đến).'},
{id:'ar05',cat:'Articles',s:'She was appointed _____ CEO of the company last January.',o:['A) a','B) an','C) the','D) no article'],a:2,e:'"The CEO" vì công ty chỉ có một CEO (chức vụ duy nhất). Phân biệt: "She is a manager" (có nhiều manager) vs "She is the CEO" (chỉ có một CEO).'},
{id:'ar06',cat:'Articles',s:'Please submit _____ completed application form to HR department.',o:['A) a','B) an','C) the','D) no article'],a:2,e:'"The completed application form" = đơn xin việc cụ thể (người nộp đơn biết đang nói về đơn nào). Khi danh từ được xác định bởi tính từ phân từ "completed" + ngữ cảnh rõ → dùng "the".'},
{id:'ar07',cat:'Articles',s:'The company has offices in _____ United States and _____ Japan.',o:['A) the / the','B) the / no article','C) no article / no article','D) a / the'],a:1,e:'Tên nước thường KHÔNG có mạo từ. Ngoại lệ: "the United States", "the UK", "the Philippines" (tên có danh từ chung hoặc tên số nhiều). "Japan" → không có mạo từ.'},
{id:'ar08',cat:'Articles',s:'He is _____ honest person who always keeps his word.',o:['A) a','B) an','C) the','D) no article'],a:1,e:'"An honest" vì "honest" bắt đầu bằng âm nguyên âm /ɒnɪst/ (chữ H câm). Tương tự: "an hour", "an honor", "an heir". Quy tắc: dựa vào âm thanh đầu tiên.'},
{id:'ar09',cat:'Articles',s:'_____ rich should contribute more to society through taxes.',o:['A) A','B) An','C) The','D) No article'],a:2,e:'"The + adj" = một nhóm người. "The rich" = những người giàu (= rich people). Tương tự: "the poor", "the elderly", "the unemployed". Không cần danh từ phía sau.'},
{id:'ar10',cat:'Articles',s:'We will schedule _____ meeting to discuss the quarterly results.',o:['A) a','B) an','C) the','D) no article'],a:0,e:'"A meeting" = một cuộc họp (chưa cụ thể, lần đầu đề cập). Dùng "a" vì chưa xác định cuộc họp cụ thể nào. Nếu đã nói đến trước: "Let\'s reschedule the meeting."'},

// REPORTED SPEECH - 5 new
{id:'rs01',cat:'Reported Speech',s:'He said that he _____ to submit the report the following day.',o:['A) will try','B) would try','C) tries','D) tried'],a:1,e:'Trong reported speech, "will" → "would". "He said: I will try..." → "He said (that) he would try...". Lùi thì: will → would, can → could, may → might.'},
{id:'rs02',cat:'Reported Speech',s:'The manager asked the intern _____ she had finished the task.',o:['A) that','B) if','C) what','D) whether or not'],a:1,e:'Câu hỏi Yes/No trong reported speech dùng "if" hoặc "whether". "Did you finish?" → "He asked if she had finished". Lùi thì: did → had done.'},
{id:'rs03',cat:'Reported Speech',s:'She told me _____ to worry about the deadline.',o:['A) do not','B) not to','C) to not','D) that not'],a:1,e:'Mệnh lệnh phủ định trong reported speech: "not to + V". "Don\'t worry" → "She told me not to worry". Cấu trúc: tell/ask + O + (not) to + V.'},
{id:'rs04',cat:'Reported Speech',s:'He explained that profits _____ by 15% the previous year.',o:['A) increase','B) increased','C) had increased','D) would increase'],a:2,e:'Lùi thì trong reported speech: quá khứ đơn → quá khứ hoàn thành. "Profits increased last year" → "He explained that profits had increased the previous year".'},
{id:'rs05',cat:'Reported Speech',s:'The client asked _____ the product would be delivered.',o:['A) that','B) if','C) when','D) what time'],a:2,e:'Câu hỏi Wh- trong reported speech dùng từ để hỏi gốc. "When will the product be delivered?" → "The client asked when the product would be delivered". Lùi thì: will → would.'},

// COMPARISON - 5 more
{id:'cp06',cat:'Comparison',s:'The new model is not _____ the previous one in terms of battery life.',o:['A) as good as','B) better than','C) the best of','D) good as'],a:0,e:'"Not as good as" = so sánh ngang bằng phủ định. "A is not as + adj + as B" = A kém hơn B. "Not as good as" = không tốt bằng. Phân biệt với "worse than".'},
{id:'cp07',cat:'Comparison',s:'The sooner we address this issue, _____ it will be to resolve.',o:['A) easy','B) easier','C) the easier','D) the easiest'],a:2,e:'Cấu trúc "The + so sánh hơn..., the + so sánh hơn...": "The sooner..., the easier...". Phải có "the" trước cả hai so sánh hơn trong cấu trúc này.'},
{id:'cp08',cat:'Comparison',s:'Our latest model is by far _____ in the product line.',o:['A) more advanced','B) the most advanced','C) most advanced','D) as advanced'],a:1,e:'"By far the most + adj" = vượt trội hơn nhiều so với tất cả. "By far" nhấn mạnh mức độ chênh lệch lớn của so sánh nhất. Cần có "the" trước so sánh nhất.'},
{id:'cp09',cat:'Comparison',s:'The project took _____ than we had anticipated.',o:['A) longer','B) more long','C) longest','D) most long'],a:0,e:'"Longer" = so sánh hơn bất quy tắc của "long". Tính từ ngắn (1 âm tiết): thêm -er. "Long → longer → longest". Không dùng "more long" (sai).'},
{id:'cp10',cat:'Comparison',s:'This quarter\'s results are _____ those of the same period last year.',o:['A) superior to','B) superior than','C) more superior to','D) superior as'],a:0,e:'"Superior to" = tốt hơn, ưu việt hơn. Collocation cố định: superior TO (không phải "than"). Tương tự: "inferior to", "prior to", "preferable to".'},

// PREPOSITIONS - 10 more
{id:'pr11',cat:'Prepositions',s:'The project is on schedule and is expected to be completed _____ time.',o:['A) in','B) on','C) at','D) by'],a:0,e:'"In time" = đúng giờ, kịp lúc (không trễ). Phân biệt: "on time" = đúng giờ đã hẹn/lịch trình. "In time" nhấn mạnh đến trước deadline. Cả hai đều đúng ở đây nhưng "in time" phổ biến hơn với "expected".'},
{id:'pr12',cat:'Prepositions',s:'She has been absent _____ the office for three days.',o:['A) of','B) at','C) from','D) in'],a:2,e:'"Absent from" = vắng mặt khỏi. Collocation cố định. Tương tự: "separate from", "different from", "exclude from". "Absent" luôn đi với giới từ "from".'},
{id:'pr13',cat:'Prepositions',s:'The new policy takes effect _____ 1 January next year.',o:['A) in','B) on','C) at','D) from'],a:1,e:'"On + ngày/ngày tháng cụ thể". "On 1 January" = vào ngày 1 tháng 1. Phân biệt: "in January" (tháng), "on January 1st" (ngày cụ thể), "at noon" (giờ cụ thể).'},
{id:'pr14',cat:'Prepositions',s:'The manager is responsible _____ ensuring workplace safety.',o:['A) of','B) to','C) for','D) with'],a:2,e:'"Responsible for + V-ing/noun" = chịu trách nhiệm về. Giới từ cố định. Phân biệt: "responsible to someone" (chịu trách nhiệm trước ai đó) vs "responsible for something" (chịu trách nhiệm về điều gì).'},
{id:'pr15',cat:'Prepositions',s:'The seminar focused _____ developing communication skills.',o:['A) at','B) in','C) about','D) on'],a:3,e:'"Focus on + V-ing/noun" = tập trung vào. Collocation cố định. Tương tự: "concentrate on", "insist on", "depend on". Luôn dùng "on" sau "focus".'},
{id:'pr16',cat:'Prepositions',s:'The company has been struggling _____ financial difficulties for months.',o:['A) against','B) from','C) with','D) by'],a:2,e:'"Struggle with" = gặp khó khăn với, đấu tranh với (vấn đề). "Struggle against" = đấu tranh chống lại (đối thủ/lực cản bên ngoài). Tài chính là vấn đề nội tại → "with".'},
{id:'pr17',cat:'Prepositions',s:'Please be aware _____ the changes to the refund policy.',o:['A) of','B) about','C) with','D) for'],a:0,e:'"Aware of" = nhận thức về, biết về. Collocation cố định. "Be aware of" thường gặp trong thông báo kinh doanh. Phân biệt: "informed about" (được thông báo về), "aware of" (nhận thức được).'},
{id:'pr18',cat:'Prepositions',s:'The decision was made _____ consultation with all stakeholders.',o:['A) after','B) during','C) in','D) following'],a:2,e:'"In consultation with" = sau khi tham khảo ý kiến. Cụm giới từ cố định trong văn bản trang trọng. Tương tự: "in accordance with" (theo đúng), "in line with" (phù hợp với).'},
{id:'pr19',cat:'Prepositions',s:'The store offers a 10% discount _____ all purchases over $100.',o:['A) for','B) in','C) on','D) at'],a:2,e:'"Discount on" = giảm giá trên. "A discount on purchases/products" là collocation chuẩn. Phân biệt: "discount for students/members" (giảm giá dành cho đối tượng cụ thể).'},
{id:'pr20',cat:'Prepositions',s:'The board approved the budget _____ a majority vote.',o:['A) with','B) by','C) through','D) via'],a:1,e:'"By + phương thức" = bằng cách. "By a majority vote" = bằng cuộc bỏ phiếu đa số. "By" thường dùng với phương tiện/phương thức: "by email", "by phone", "by a vote".'},

// CONJUNCTIONS - 5 more
{id:'cj11',cat:'Conjunctions',s:'The meeting was productive; _____, several key issues remain unresolved.',o:['A) moreover','B) however','C) therefore','D) furthermore'],a:1,e:'"However" = tuy nhiên, thể hiện tương phản. "The meeting was productive" (tích cực) + tương phản + "issues unresolved" (tiêu cực) → "however". "Moreover/Furthermore" thêm ý, "therefore" = kết quả.'},
{id:'cj12',cat:'Conjunctions',s:'We offer competitive salaries _____ excellent benefits packages.',o:['A) so that','B) although','C) as well as','D) unless'],a:2,e:'"As well as" = cũng như, cùng với. Liên kết hai danh từ/cụm danh từ tương đương. "Competitive salaries as well as benefits" = cả hai đều được đề cập. Trang trọng hơn "and".'},
{id:'cj13',cat:'Conjunctions',s:'_____ the project was delayed, it was still completed within budget.',o:['A) As a result','B) In spite of','C) Even though','D) Due to'],a:2,e:'"Even though" + mệnh đề đầy đủ (S+V) = mặc dù (nhấn mạnh sự ngạc nhiên hơn "although"). "In spite of/Due to" + danh từ/V-ing. "As a result" = kết quả (không phải tương phản).'},
{id:'cj14',cat:'Conjunctions',s:'We must reduce costs; _____, we will not be able to stay competitive.',o:['A) therefore','B) however','C) otherwise','D) moreover'],a:2,e:'"Otherwise" = nếu không (thì). Nêu hậu quả nếu điều kiện không được thực hiện. "We must reduce costs; otherwise, we will not..." = Nếu không giảm chi phí, sẽ không thể cạnh tranh.'},
{id:'cj15',cat:'Conjunctions',s:'The company succeeded _____ the challenging economic conditions.',o:['A) although','B) in spite of','C) even though','D) however'],a:1,e:'"In spite of + noun/V-ing" = mặc dù. "The challenging economic conditions" là danh từ → "in spite of". "Although/Even though" cần mệnh đề đầy đủ (S+V) theo sau.'},
];


// ── STOP WORDS (articles, prepositions, conjunctions - skip tooltip) ──
